from pathlib import Path
p=Path('tmp/pdfs/build_submission.py');s=p.read_text()
s=s.replace('Launch screening coverage and interview scheduling for approved frontline roles.','Protect interview time from unsuitable candidates and move qualified candidates promptly to a confirmed booking.')
s=s.replace("y=heading('The problem is recruiter capacity',y)","y=heading('Protect interview time and retain qualified candidates',y)")
s=s.replace("Recruiters cannot read every application; gap resolution and scheduling add work. Ladders reported a <b>7.4 second initial scan</b>, not a full assessment [1]. Time pressure is our case hypothesis. In Cronofy\\'s survey, <b>42%</b> had left a process because scheduling took too long [2].", "Unsuitable candidates consume panel time; qualified candidates can slip through before an interview is booked. <b>Delayed contact is a major driver of candidate loss in this case.</b> Screening mistakes are another risk, whose size needs validation. Recruiter capacity and scheduling effort contribute to these outcomes. Ladders reported a 7.4 second initial scan [1]; Cronofy found 42% had left a process over scheduling delays [2].")
s=s.replace("<b>1  Screening quality and fairness.</b> Proposed pilot ceiling: no more than 2% of independently assessed qualified candidates incorrectly excluded. Sample every score band; report uncertainty and investigate unexplained group differences where lawful.","<b>1  Screening quality and fairness.</b> Reduce interviewer-confirmed unsuitable referrals against baseline. Proposed pilot ceiling: no more than 2% of independently assessed qualified candidates incorrectly excluded. Sample every score band; report uncertainty and investigate unexplained group differences where lawful.")
p.write_text(s);Path('tmp/pdfs/build_decision_only.py').write_text(s[:s.index('# D2\n')])
